function nav(){let a=[['inicio',role==='client'?'Mi portal':'Mi trabajo'],['proyectos','Proyectos'],['expedientes',role==='client'?'Mis expedientes':'Expedientes'],['documentos','Documentos']];if(role!=='client')a.push(['clientes','Clientes'],['agenda','Agenda y tareas'],['plazos','Notificaciones y plazos'],['casillas','Control de casillas'],['auditoria','Historial y reportes'],['ia','IA futura']);if(visible().some(econ))a.push(['finanzas','Costos y facturación']);if(['manager','superadmin','lawyer'].includes(role))a.push(['importacion','Importación']);if(role==='superadmin')a.push(['usuarios','Cuentas y usuarios'],['configuracion','Administración']);a.push(['sesion','Sesión y seguridad']);return a;}
