function home(){if(role==='client')return page('Hola, Alejandro','Consulta el contenido expresamente publicado para tu cuenta.',note('Portal de solo lectura. Sin cargas, mensajes, edición ni invitaciones.')+card('Mis expedientes',caseList())+card('Documentos publicados',docList()));let cs=visible(),ds=db.deadlines.filter(d=>cs.some(c=>c.id===d.caseId));return page('Mi trabajo','Sábado, 31 de octubre de 2026 · Lo que necesita tu atención.',`<div class="metrics">${[['Expedientes autorizados',cs.length,globalAccess()?'Toda la cartera del estudio':'Solo expedientes asignados'],['Por verificar',ds.filter(d=>d.status==='Pendiente de verificación').length,'Requiere otro abogado'],['Notificaciones sin tratar',db.notices.filter(n=>!n.treated&&can(lookup(n.caseId),'read')).length,'Un PDF no resuelve el seguimiento'],['Cargas en revisión',db.docs.filter(d=>!d.reviewed&&!d.removed&&can(lookup(d.caseId),'read')).length,'Antes de publicar al cliente']].map(m=>`<div class="metric"><div class="metric-top">${m[0]}</div><strong>${m[1]}</strong><small>${m[2]}</small></div>`).join('')}</div><div class="layout"><div>${card('Expedientes de mi ámbito',caseList(visible().slice(0,5)),btn('Ver cartera',"go('expedientes')",true))}${card('Plazos de los próximos 15 días',deadlineList(),btn('Ver plazos',"go('plazos')",true))}</div><div>${card('Centro de alertas',`<div class="alert-item">Verificación pendiente<small>Los plazos sin verificar siguen visibles y alertando.</small></div><div class="alert-item">${db.boxChecked?'Casilla revisada':'Revisión de casilla pendiente'}<small>Escalamiento al suplente al cierre del horario.</small></div><div class="alert-item">Correo de alerta · envío fallido<small>Reintento pendiente. Aceptación no equivale a lectura.</small></div>`,btn('Control de casillas',"go('casillas')",true))}${card('Accesos por perfil',note('Gerente y superadministrador ven todos los expedientes y gestionan los accesos. Abogados y asistentes ven solo los asignados; clientes, solo contenido publicado para ellos.'))}</div></div>`,visible().some(c=>can(c,'create'))?btn('Nuevo proyecto',"newProject()"): '');}
function detail(){let c=cur();if(!c)return page('Contenido no disponible','No tienes una autorización vigente.',note('La siguiente consulta o descarga requiere acceso actual.'),btn('Volver',"go('expedientes')",true));let labels={resumen:'Resumen',cronologia:'Cronología',documentos:'Documentos',plazos:'Plazos',tareas:'Tareas',equipo:'Equipo y accesos',historial:'Historial'},tabs=role==='client'?['resumen','cronologia','documentos']:Object.keys(labels),body='';if(tab==='resumen')body=card('Ficha del expediente',`<div class="meta-grid"><div><small>Cliente / proyecto</small>${esc(c.client)} · ${c.project}</div><div><small>Tipo / etapa</small>${esc(c.type)} · ${esc(c.stage)}</div><div><small>Estado operativo</small>${tag(c.status)}</div><div><small>Contacto responsable</small>${esc(c.lawyer)}</div>${role!=='client'?`<div><small>Seguimiento</small>${esc(c.follow)}</div><div><small>Suplente</small>${esc(c.backup)}</div><div><small>Próxima acción</small>${esc(c.next)}</div>`:''}</div>`)+(role!=='client'?card('Acciones',`<div class="actions">${can(c,'edit')?btn('Registrar actuación',"newAct()"):''}${can(c,'propose')?btn('Registrar notificación',"newNotice()",true):''}${can(c,'access')?btn('Transferir abogado',"transfer()",true):''}${econ(c)?btn('Economía autorizada',"go('finanzas')",true):''}</div>`):'');if(tab==='cronologia')body=card('Actuaciones y revisiones',db.acts.filter(a=>a.caseId===c.id&&(role!=='client'||a.published)).map(a=>`<article class="timeline-item"><b>${esc(a.title)}</b><small>${esc(a.author)} · ${a.date} · ${a.published?'Revisión publicada':'Interno'}</small><p>${esc(a.text)}</p>${can(c,'publish')&&!a.published?btn('Publicar actuación',`publishAct(${db.acts.indexOf(a)})`,true):''}</article>`).join('')||note('No hay actuaciones disponibles.'));if(tab==='documentos')body=card('Versiones documentales',docList(c.id),can(c,'upload')?btn('Incorporar documento',"uploadDoc()"): '');if(tab==='plazos')body=card('Plazos del expediente',deadlineList(c.id),can(c,'propose')?btn('Proponer plazo',"newDeadline()"): '');if(tab==='tareas')body=tasks(c.id);if(tab==='equipo')body=team(c);if(tab==='historial')body=history(c.id);return page(esc(c.name),`${c.id} · ${c.project} · ${role==='client'?'Contenido publicado':'Expediente privado'}`,`<div class="tabs" aria-label="Secciones del expediente">${tabs.map(t=>`<button class="${tab===t?'active':''}" aria-pressed="${tab===t}" onclick="tab='${t}';render()">${labels[t]}</button>`).join('')}</div>${body}`,btn('← Expedientes',"go('expedientes')",true));}
function docList(caseId){let ds=db.docs.filter(d=>(!caseId||d.caseId===caseId)&&can(lookup(d.caseId),'read')&&(d.classification!=='Económica'||econ(lookup(d.caseId)))&&(role==='client'?d.published&&!d.removed:!d.removed||can(lookup(d.caseId),'delete')));return ds.map(d=>{let c=lookup(d.caseId);return `<article class="doc-item"><div class="doc-icon">${esc(d.name.split('.').pop().toUpperCase())}</div><div class="grow"><b>${esc(d.name)}</b><small>${d.caseId} · ${role==='client'?'Versión publicada '+d.published:'Versión interna '+d.version+' · '+d.author} · ${d.size}</small>${role!=='client'&&d.history?'<small>Autoría conservada: '+d.history.map(v=>'v'+v.version+' · '+esc(v.author)).join(' / ')+'</small>':''}<div class="tags">${tag(d.removed?'Baja lógica':role==='client'?'Publicado para ti':d.reviewed?'Revisado':'Pendiente de revisión',d.reviewed?'':'gold')}${role!=='client'?tag(d.published?'Publicada v'+d.published:'Interno'):''}</div></div><div class="actions">${!d.removed&&can(c,'download')?btn('Ver / descargar',`previewDoc(${d.id})`,true):''}${role!=='client'&&!d.removed&&can(c,'publish')?btn(d.reviewed?'Publicar versión':'Revisar',`${d.reviewed?'publishDoc':'reviewDoc'}(${d.id})`,true):''}${d.published&&can(c,'publish')?btn('Retirar publicación',`unpublish(${d.id})`,true):''}${ocrAllowed(d)?btn(d.ocr?.version===d.version?'Revisar texto OCR':'Extraer texto (OCR)',`ocrDemo(${d.id})`,true):''}${can(c,'upload')&&!d.removed?btn('Nueva versión',`uploadDoc(${d.id})`,true):''}${role!=='client'?(can(c,'delete')?btn(d.removed?'Recuperar':'Tramitar baja',`removeDoc(${d.id})`,true):btn('Solicitar baja',`requestRemoval(${d.id})`,true)):''}</div></article>`;}).join('')||note('No hay documentos disponibles para tu acceso.');}
